pageStyle:
table.groups-4-portal {
text-align: left;
font-size: 13px;
}

table.groups-4-portal th {
	height: 250px;
vertical-align: bottom;
}

table.groups-4-portal th span{
	display: block;
 white-space: nowrap;
	transform: rotate(-90deg);
	transform-origin: bottom left;
	position:absolute;
	left: 25px;
	bottom: 5px;
}

table.groups-4-portal th, table.groups-4-portal td {
	position: relative;
	padding: 3px;
	text-align: center;
}

table.groups-4-portal .td-marked{
	background-color: #ffcc00;
}

table.groups-4-portal tr td:first-child {
	font-weight: bold;
	font-size: 14px;
}

.portal-bubble {
    color: #06f !important;
    background-color: #dddddd;
    font-size: 14px !important;
}
